parameters.jsCode:
const items = $input.all();
const results = [];

for (const item of items) {
  try {
    const raw = item.json.content[0].text;
    const cleaned = raw.replace(/```json\n?/g, '').replace(/```/g, '').trim();
    const calificacion = JSON.parse(cleaned);

    results.push({
      json: {
        Score_Total: calificacion.score_total,
        Intencion: calificacion.intencion,
        Urgencia: calificacion.urgencia,
        Fit_Servicio: calificacion.fit_servicio,
        Facilidad_Contacto: calificacion.facilidad_contacto,
        Prioridad: calificacion.prioridad,
        Razonamiento: calificacion.razonamiento
      }
    });
  } catch(e) {
    results.push({
      json: {
        Score_Total: 0,
        Intencion: 0,
        Urgencia: 0,
        Fit_Servicio: 0,
        Facilidad_Contacto: 0,
        Prioridad: "error",
        Razonamiento: e.message
      }
    });
  }
}

return results;
